function doStub(env){return env.CRM.get(env.CRM.idFromName("n7demo-main"))}
function guestContext(req){let id=cookie(req,GUEST_COOKIE),fresh=false;if(!id){id=rand(18);fresh=true}return{id,workspaceId:"guest-"+id,actorSub:"guest:"+id,fresh,cookie:fresh?sessionCookie(GUEST_COOKIE,id):""}}
async function currentSession(req,env){const sid=cookie(req,SESSION_COOKIE);if(!sid)return null;const stub=doStub(env);let r=await stub.fetch("https://internal/session/"+encodeURIComponent(sid));if(!r.ok)return null;let s=await r.json();let user=null;if(Number(s.expiresAt||0)>Date.now()+30000)user=await userInfo(s.accessToken).catch(()=>null);if(!user){const nt=await refreshTokens(s).catch(()=>null);if(!nt)return null;await stub.fetch("https://internal/session/"+encodeURIComponent(sid),{method:"PATCH",headers:{"content-type":"application/json"},body:JSON.stringify(nt)});user=await userInfo(nt.accessToken).catch(()=>null);if(!user)return null;s={...s,...nt}}if(!userAllowed(user))return null;return {sid,user,workspaceId:WORKSPACE_ID}}
async function finishLogin(req,env){const u=new URL(req.url),code=u.searchParams.get("code")||"",state=u.searchParams.get("state")||"",tx=cookie(req,TX_COOKIE),dot=tx.indexOf("."),expected=dot>0?tx.slice(0,dot):"",verifier=dot>0?tx.slice(dot+1):"";if(!code||!state||state!==expected||!verifier)return html("<h1>Login could not be completed</h1>",400,{"set-cookie":clearCookie(TX_COOKIE)});const cfg=await authConfig();const tr=await fetch(cfg.token_endpoint,{method:"POST",headers:{"content-type":"application/x-www-form-urlencoded",accept:"application/json"},body:new URLSearchParams({grant_type:"authorization_code",client_id:cfg.client_id,code,redirect_uri:cfg.redirect_uri,code_verifier:verifier})});const tok=await tr.json().catch(()=>({}));if(!tr.ok||!tok.access_token)return html("<h1>Clintware Identity did not issue a usable token.</h1>",502);const user=await userInfo(tok.access_token);if(!userAllowed(user))return html("<h1>Access is not authorized for this CRM.</h1>",403);const sid=rand(32),expiresAt=Date.now()+Number(tok.expires_in||900)*1000;await doStub(env).fetch("https://internal/session",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({id:sid,user,accessToken:tok.access_token,refreshToken:tok.refresh_token||"",expiresAt})});const h=secureHeaders(new Headers({location:"/","set-cookie":setCookie(SESSION_COOKIE,sid,30*24*60*60)}));h.append("set-cookie",clearCookie(TX_COOKIE));return new Response(null,{status:302,headers:h})}

